B.b4n=new A.eE([B.jp,"Find a masjid near you","Mosques around you, on a map","/masajid"])
B.ak2=new A.ac(61484,"MaterialIcons",null,!1)
B.b4l=new A.eE([B.ak2,"Jumu\u2019ah and prayer times","Set your masjid\u2019s Friday time","/prayer"])
